sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var msg = "";
    switch (newValue) {
        case 'once_daily':
		msg="Take one dose every 24 hours.";
		break;
		case 'twice_daily':
		msg="Take one dose every 12 hours.";
		break;
		case 'thrice_daily':
		msg="ake one dose every 8 hours.";
		break;
		default:
		msg="Please follow your doctor\'s prescription.";

    }
	//false Scroll down off kr deta h
	g_form.showFieldMsg("u_frequency",msg,'info',false);

    //Type appropriate comment here, and begin script below

}
